import{t as e}from"./jsx-runtime-BqfDQeLH.js";import{t}from"./PolicyPage-D3d-Ay9o.js";var n=e(),r=[{heading:`Community First`,paragraphs:[`We prioritise practical needs such as communication, participation, safety, events, records and access to local opportunities.`,`Features should create genuine value and should not manipulate users into unnecessary activity or spending.`]},{heading:`Trust and Transparency`,paragraphs:[`We aim to explain important controls, charges, permissions and data uses in clear language, consistent with Nigerian consumer and data-protection requirements.`,`Material mistakes should be corrected, and significant service or policy changes should receive appropriate notice.`]},{heading:`Privacy and Security`,paragraphs:[`We use purpose limitation, data minimisation, access controls and security measures appropriate to risk under the NDP Act and GAID.`,`Passwords, verification codes and protected records must never be misused. Suspected breaches and cybercrime are investigated and escalated where legally required.`]},{heading:`Inclusion and Respect`,paragraphs:[`We oppose harassment, unlawful discrimination and exclusion. Product and moderation decisions should consider people with different abilities, languages and levels of digital experience.`,`Child safety and the protection of vulnerable users require heightened care and proportionate safeguards.`]},{heading:`Fairness and Consumer Protection`,paragraphs:[`We do not seek to waive mandatory rights under the FCCPA or misrepresent third-party goods, services or payment providers.`,`Marketplace and service information should be accurate, and users should receive meaningful complaint and redress routes.`]},{heading:`Integrity and Lawful Conduct`,paragraphs:[`We reject fraud, bribery, impersonation, diversion of community funds, intellectual-property infringement and abuse of administrative power.`,`The Copyright Act 2022, cybercrime rules and other applicable Nigerian laws inform platform policies and enforcement.`]},{heading:`Accountability and Improvement`,paragraphs:[`We consider context and proportionality when enforcing rules and provide review routes where appropriate.`,`Feedback, support reports, security findings and regulator guidance inform continuous improvement.`]}];function i(){return(0,n.jsx)(t,{intro:`Our values guide product design, community relationships, moderation and compliance decisions across CDA Connect.`,sections:r})}export{i as default};
